#!/bin/bash
# ---------------------------------------------------------------------------
# AUTO-GENERATED by Claude Code
# Purpose: first-run bootstrap for a fresh Omarchy machine: installs uv (not in stock Omarchy),
# then runs `os sync`, which sets the machine up from .os/machine.toml. Afterwards a new terminal
# has the `os` alias.
#
# Example CLI Commands:
#   1. New machine:  git clone <repo> ~/repos/delulu-smash && ~/repos/delulu-smash/.os/install.sh
#   2. Preview only: ~/repos/delulu-smash/.os/install.sh --dry-run
# ---------------------------------------------------------------------------
set -euo pipefail

repo="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
command -v uv >/dev/null || sudo pacman -S --needed --noconfirm uv
exec uv run "$repo/.os/cli.py" sync "$@"
